import java.util.*;

public class Main {
    public static void main(String[] a) {
        Scanner sc = new Scanner(System.in);
        int n = Integer.parseInt(sc.nextLine().trim());
        String mark = "omitted for conflict with ";
        List<String[]> conflicts = new ArrayList<>();
        for (int i = 0; i < n; i++) {
            String line = sc.nextLine();
            int at = line.indexOf(mark);
            if (at < 0) continue;                       // duplicate や通常の行は対象外
            String winner = line.substring(at + mark.length()).trim();
            String[] parts = coordinate(line).split(":");
            conflicts.add(new String[] {parts[1], winner, parts[3]});
        }
        if (conflicts.isEmpty()) {
            System.out.println("OK");
            return;
        }
        conflicts.sort(Comparator.<String[], String>comparing(c -> c[0]).thenComparing(c -> c[2]));
        for (String[] c : conflicts) {
            System.out.println("CONFLICT " + c[0] + " " + c[1] + " " + c[2]);
        }
    }

    /** 行の中から `groupId:artifactId:jar:版:範囲` の形の語を取り出す。 */
    static String coordinate(String line) {
        for (String token : line.split("\\s+")) {
            if (token.split(":").length >= 4) return token;
        }
        throw new IllegalArgumentException(line);
    }
}

