import java.util.*;

public class Main {
    public static void main(String[] a) {
        Scanner sc = new Scanner(System.in);
        int t = Integer.parseInt(sc.nextLine().trim());
        List<String> frames = new ArrayList<>();
        for (int i = 0; i < t; i++) {
            String line = sc.nextLine().trim();
            if (!line.startsWith("at ")) continue;          // 例外名の行などは飛ばす
            int open = line.lastIndexOf('(');
            frames.add(line.substring(open + 1, line.lastIndexOf(')')));
        }
        int f = Integer.parseInt(sc.nextLine().trim());
        Set<String> flagged = new HashSet<>();
        for (int i = 0; i < f; i++) {
            String where = sc.nextLine().trim().split("\\s+")[0];
            flagged.add(where.substring(where.lastIndexOf('/') + 1));
        }
        boolean any = false;
        for (String frame : frames) {
            if (flagged.contains(frame)) {
                System.out.println("SUSPECT " + frame);
                any = true;
            }
        }
        if (!any) System.out.println("NO_MATCH");
    }
}

