import java.util.*;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        Set<String> selfs = new TreeSet<>();
        Set<String> edges = new LinkedHashSet<>();
        Map<String, Integer> depended = new TreeMap<>();
        List<String[]> pairs = new ArrayList<>();
        for (int i = 0; i < n; i++) {
            String module = sc.next(), dependency = sc.next();
            if (module.equals(dependency)) {
                selfs.add(module);
                continue;
            }
            edges.add(module + ">" + dependency);
            pairs.add(new String[] {module, dependency});
            depended.merge(dependency, 1, Integer::sum);
        }
        for (String m : selfs) System.out.println("SELF " + m);
        Set<String> shown = new TreeSet<>();
        for (String[] p : pairs) if (edges.contains(p[1] + ">" + p[0])) {
            String a = p[0].compareTo(p[1]) <= 0 ? p[0] : p[1], b = p[0].compareTo(p[1]) <= 0 ? p[1] : p[0];
            shown.add(a + " " + b);
        }
        for (String c : shown) System.out.println("CYCLE " + c);
        if (selfs.isEmpty() && shown.isEmpty()) System.out.println("ACYCLIC");
        String best = "NONE";
        int bestCount = 0;
        for (Map.Entry<String, Integer> e : depended.entrySet()) if (e.getValue() > bestCount) {
            best = e.getKey();
            bestCount = e.getValue();
        }
        System.out.println("MOST_DEPENDED " + best + " " + bestCount);
    }
}

